    private static <T> void clearRangeFromCache(@Nonnull ConcurrentNavigableMap<byte[], T> cache, @Nonnull Range range) {
        // Range is a half-open interval [begin, end).
        cache.subMap(range.begin, true, range.end, false).clear();
    }

