+    /**
+     * Clear a single key from the database. In addition to issuing a clear against the underlying
+     * transaction, this removes any uncommitted versionstamp mutation and any cached local version
+     * associated with the given key. This ensures that a key that is cleared within a transaction does
+     * not have a stale versionstamp mutation flushed to the database at commit time (which could otherwise
+     * resurrect data that was supposed to have been deleted).
+     *
+     * @param key the key to clear
+     * @see Transaction#clear(byte[])
+     */
+    @SuppressWarnings("PMD.CloseResource")
+    public void clear(@Nonnull byte[] key) {
+        ensureActive().clear(key);
+        versionMutationCache.remove(key);
+        localVersionCache.remove(key);
+    }
+
+    /**
+     * Clear a range of keys from the database. In addition to issuing a clear against the underlying
+     * transaction, this removes any uncommitted versionstamp mutations and any cached local versions
+     * for keys within the given range. This ensures that keys that are cleared within a transaction do
+     * not have stale versionstamp mutations flushed to the database at commit time (which could otherwise
+     * resurrect data that was supposed to have been deleted).
+     *
+     * @param range the range of keys to clear
+     * @see Transaction#clear(Range)
+     */
+    @SuppressWarnings("PMD.CloseResource")
+    public void clear(@Nonnull Range range) {
+        ensureActive().clear(range);
+        clearRangeFromCache(versionMutationCache, range);
